<?php
require_once 'config/layout.php';require_once 'config/guidance.php';require_login();$uid=(int)current_user()['id'];$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf($_POST['csrf']??null);try{$action=input_text('action',20);$type=input_text('type',20);$id=input_text('id',200);if(!in_array($type,['career','programme','scholarship'],true))throw new InvalidArgumentException('Unknown saved item type.');if($action==='remove'){db()->prepare('DELETE FROM saved_items WHERE user_id=? AND item_type=? AND item_id=?')->execute([$uid,$type,$id]);}elseif($action==='save'){$title=null;if($type==='career'){foreach(reference_careers() as $r)if($r['title']===$id)$title=$r['title'];}else{$table=$type==='programme'?'programmes':'scholarships';$s=db()->prepare('SELECT title FROM '.$table.' WHERE id=?');$s->execute([$id]);$title=$s->fetchColumn();}if(!$title)throw new InvalidArgumentException('This item is no longer in the directory.');db()->prepare('INSERT IGNORE INTO saved_items(user_id,item_type,item_id,title) VALUES(?,?,?,?)')->execute([$uid,$type,$id,$title]);}else throw new InvalidArgumentException('Unknown action.');header('Location: progress.php');exit;}catch(InvalidArgumentException $ex){$error=$ex->getMessage();}}
$s=db()->prepare('SELECT * FROM saved_items WHERE user_id=? ORDER BY created_at DESC');$s->execute([$uid]);$items=$s->fetchAll();$s=db()->prepare('SELECT p.*,COUNT(m.id) total,SUM(m.completed_at IS NOT NULL) done FROM career_plans p LEFT JOIN roadmap_milestones m ON m.plan_id=p.id WHERE p.user_id=? GROUP BY p.id ORDER BY p.id DESC');$s->execute([$uid]);$plans=$s->fetchAll();page_start('My progress');
?>
<main id="main" class="wide page-space"><div class="page-intro"><h1><?= e(t('My progress')) ?></h1><p>Your saved options, goals and completed activities in one place.</p></div><div class="tool-links"><a class="btn btn-primary" href="roadmap.php">Create a roadmap</a><a class="btn btn-outline" href="history.php">Assessment history</a><a class="btn btn-outline" href="report.php">Download guidance PDF</a></div><?php if($error):?><p class="alert error" role="alert"><?= e($error) ?></p><?php endif;?><h2>Career plans</h2><div class="careers-grid"><?php foreach($plans as $p):?><article class="panel"><h3><?= e($p['career_title']) ?></h3><p><?= (int)$p['done'] ?> of <?= (int)$p['total'] ?> milestones complete</p><a href="roadmap.php?id=<?= (int)$p['id'] ?>">Edit and track plan ↗</a></article><?php endforeach;?></div><?php if(!$plans):?><p class="panel">No plans yet. Choose a career and create your first development roadmap.</p><?php endif;?><h2>Saved opportunities</h2><div class="careers-grid"><?php foreach($items as $item):?><article class="panel"><span class="badge"><?= e($item['item_type']) ?></span><h3><?= e($item['title']) ?></h3><p><a href="<?= $item['item_type']==='career'?'compare.php?career='.e(urlencode($item['item_id'])):($item['item_type']==='programme'?'directory.php':'scholarships.php').'?q='.e(urlencode($item['title'])) ?>">Explore this option ↗</a></p><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="remove"><input type="hidden" name="type" value="<?= e($item['item_type']) ?>"><input type="hidden" name="id" value="<?= e($item['item_id']) ?>"><button class="btn btn-outline">Remove saved item</button></form></article><?php endforeach;?></div><?php if(!$items):?><p class="panel">Save careers, programmes or funding opportunities from their directories.</p><?php endif;?></main><?php page_end(); ?>
